import React, { useState, useCallback, useMemo, useRef } from 'react';
import { useInAppNavigate } from '../../../router/useInAppNavigate';

import {
  Select,
  dispatchAppToast,
  LIN_ERP_LIST_FILTER_LAYOUT,
  LinErpListFilterBar,
  LinPageLayout,
  LinReportPeriodSelectorFields,
  computeReportPeriodDates,
  nowMonth,
  nowYear,
  nowQuarter,
  yearOptionsFromStartYear,
  type ViewMode,
} from '@linm-soft-org/linm-web-common-components';
import { DocumentProcessingLevelPill } from '../../../components/document/DocumentProcessingLevelPill';
import {
  COST_SHEET_LEVEL_FILTER_OPTIONS,
  formatCostSheetProcessingLevel,
} from '../../../utils/documentProcessingLevelDisplay';
import { useAppDispatch } from '../../../store/hooks';
import { gtService } from '../../../services/gt/gtService';
import type { CostSheetDto, CostSheetFilter, WipBalanceDto } from '../../../services/gt/models';
import { giaThanhPageLabels as L } from '../../../constants/giaThanhPageLabels';
import { formatVnd } from '../../../utils/formatters';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { useCostSheetPermissions } from '../../../hooks/useCostSheetPermissions';
import erp from '../../../styles/erpPage.module.css';
import { useVoucherListTableBusy } from '../../../components/list/useVoucherListTableBusy';
import {
  DEFAULT_PAGE_SIZE,
  VoucherListPagination,
  type ListPageSize,
} from '../../../components/list/VoucherListPagination';

const TEST_ID = 'erp-gia-thanh';
const PAGE_ID = 'gt-gia-thanh';
const PAGE_SIZE = DEFAULT_PAGE_SIZE;

const PROCESSING_LEVEL_OPTIONS = COST_SHEET_LEVEL_FILTER_OPTIONS;

type PeriodQuery = Pick<CostSheetFilter, 'month' | 'year' | 'monthFrom' | 'monthTo'>;

function resolveCostSheetPeriodQuery(
  viewMode: ViewMode,
  month: string,
  year: string,
  quarter: string,
  fromDate: string,
): PeriodQuery {
  const y = Number(year);
  if (viewMode === 'year') {
    return { year: y };
  }
  if (viewMode === 'quarter') {
    const q = Number(quarter) || 1;
    const monthFrom = (q - 1) * 3 + 1;
    return { year: y, monthFrom, monthTo: monthFrom + 2 };
  }
  if (viewMode === 'day' && fromDate) {
    const [fy, fm] = fromDate.split('-');
    return { year: Number(fy), month: Number(fm) };
  }
  return { year: y, month: Number(month) };
}

const GiaThanhListPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useInAppNavigate();
  const { canRead } = useCostSheetPermissions();
  const startYear = import.meta.env.VITE_START_YEAR ? Number(import.meta.env.VITE_START_YEAR) : undefined;
  const yearOpts = startYear ? yearOptionsFromStartYear(startYear) : undefined;

  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [month, setMonth] = useState(nowMonth());
  const [year, setYear] = useState(nowYear());
  const [quarter, setQuarter] = useState(nowQuarter());
  const [manualFromDate, setManualFromDate] = useState('');
  const [manualToDate, setManualToDate] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<ListPageSize>(PAGE_SIZE);
  const [processingLevel, setProcessingLevel] = useState('');
  const [items, setItems] = useState<CostSheetDto[]>([]);
  const [wipRows, setWipRows] = useState<WipBalanceDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const loadErrorToastShownRef = useRef(false);

  const { showTableLoading } = useVoucherListTableBusy(loading);

  const computedDates = useMemo(() => {
    if (viewMode === 'year') {
      const y = Number(year);
      return { fromDate: `${y}-01-01`, toDate: `${y}-12-31` };
    }
    return computeReportPeriodDates(viewMode, month, year, quarter);
  }, [viewMode, month, year, quarter]);

  const fromDate = viewMode === 'day' ? manualFromDate : computedDates.fromDate;
  const toDate = viewMode === 'day' ? manualToDate : computedDates.toDate;

  const periodQuery = useMemo(
    () => resolveCostSheetPeriodQuery(viewMode, month, year, quarter, fromDate),
    [viewMode, month, year, quarter, fromDate],
  );

  const handleLoad = useCallback((opts?: { allowErrorToast?: boolean }) => {
    if (!canRead) {
      setItems([]);
      setWipRows([]);
      setTotalCount(0);
      setLoading(false);
      return;
    }
    if (opts?.allowErrorToast) {
      loadErrorToastShownRef.current = false;
    }
    setLoading(true);
    Promise.all([
      gtService.getCostSheets({
        ...periodQuery,
        processingLevel: processingLevel || undefined,
        page,
        pageSize,
      }),
      gtService.getWipBalance(periodQuery),
    ])
      .then(([res, wip]) => {
        loadErrorToastShownRef.current = false;
        setItems(res.items);
        setTotalCount(res.totalCount);
        setWipRows(wip);
      })
      .catch(err => {
        setItems([]);
        setWipRows([]);
        setTotalCount(0);
        if (!loadErrorToastShownRef.current) {
          loadErrorToastShownRef.current = true;
          dispatchAppToast(dispatch, {
            message: getApiErrorMessage(err, L.list.loadError),
            type: 'error',
          });
        }
      })
      .finally(() => setLoading(false));
  }, [canRead, periodQuery, processingLevel, page, pageSize, dispatch]);

  const refresh = useCallback(() => {
    handleLoad({ allowErrorToast: true });
  }, [handleLoad]);

  const searchLoad = useCallback(() => {
    handleLoad({ allowErrorToast: true });
  }, [handleLoad]);

  const handleDateRangeChange = useCallback(
    (from?: string, to?: string) => {
      if (!from && !to) return;
      if (viewMode !== 'day') {
        setViewMode('day');
      }
      if (from) setManualFromDate(from);
      if (to) setManualToDate(to);
      setPage(1);
    },
    [viewMode],
  );

  const handleViewModeChange = useCallback(
    (mode: ViewMode) => {
      if (mode === viewMode) return;
      if (mode === 'day') {
        let from: string;
        let to: string;
        if (viewMode === 'year') {
          const y = Number(year);
          from = `${y}-01-01`;
          to = `${y}-12-31`;
        } else {
          const currentComputed = computeReportPeriodDates(viewMode, month, year, quarter);
          from = currentComputed.fromDate;
          to = currentComputed.toDate;
        }
        setManualFromDate(from);
        setManualToDate(to);
      } else {
        setManualFromDate('');
        setManualToDate('');
      }
      if (mode === 'month') {
        setMonth(nowMonth());
        setYear(nowYear());
      } else if (mode === 'quarter') {
        setQuarter(nowQuarter());
        setYear(nowYear());
      } else if (mode === 'year') {
        setYear(nowYear());
      }
      setViewMode(mode);
      setPage(1);
    },
    [viewMode, month, year, quarter],
  );

  const wipOpening = wipRows.reduce((sum, row) => sum + row.openingAmount, 0);
  const wipClosing = wipRows.reduce((sum, row) => sum + row.closingAmount, 0);

  React.useEffect(() => {
    let cancelled = false;
    const t = setTimeout(() => {
      if (!cancelled) handleLoad();
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [handleLoad]);

  const reportToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: refresh,
      canChart: false,
      canPrint: false,
    }),
    [refresh],
  );

  const periodSelectorLabels = useMemo(
    () => ({
      viewMode: L.list.fieldViewMode,
      fieldMonth: L.list.filterMonth,
      fieldYear: L.list.filterYear,
      fieldQuarter: L.list.fieldQuarter,
    }),
    [],
  );

  const listFilters = useMemo(
    () => (
      <LinErpListFilterBar
        testIdPrefix={TEST_ID}
        fromDate={fromDate}
        toDate={toDate}
        onDateChange={handleDateRangeChange}
        dateLabel={L.list.fieldPeriod}
        onSearch={searchLoad}
        searchAriaLabel="Tìm"
        loading={showTableLoading}
        leading={(
          <div data-testid={`${TEST_ID}-field-processing-level`}>
            <Select
              label={L.list.filterProcessingLevel}
              value={processingLevel}
              onChange={e => {
                setProcessingLevel(e.target.value);
                setPage(1);
              }}
              options={PROCESSING_LEVEL_OPTIONS}
              fullWidth
              data-testid={`${TEST_ID}-processing-level`}
            />
          </div>
        )}
        dateLeading={(
          <LinReportPeriodSelectorFields
            testIdPrefix={TEST_ID}
            labels={periodSelectorLabels}
            viewMode={viewMode}
            month={month}
            year={year}
            quarter={quarter}
            yearOptions={yearOpts}
            onViewModeChange={handleViewModeChange}
            onMonthChange={value => {
              setMonth(value);
              setPage(1);
            }}
            onYearChange={value => {
              setYear(value);
              setPage(1);
            }}
            onQuarterChange={value => {
              setQuarter(value);
              setPage(1);
            }}
          />
        )}
      />
    ),
    [
      fromDate,
      toDate,
      handleDateRangeChange,
      searchLoad,
      showTableLoading,
      processingLevel,
      periodSelectorLabels,
      viewMode,
      month,
      year,
      quarter,
      yearOpts,
      handleViewModeChange,
    ],
  );

  const wipSummary = (
    <div className={erp.summaryBar} data-testid={`${TEST_ID}-wip-summary`}>
      <div className={erp.summaryItem}>
        <label className={erp.label}>{L.list.wipOpening}</label>
        <strong>{formatVnd(wipOpening)}</strong>
      </div>
      <div className={erp.summaryItem}>
        <label className={erp.label}>{L.list.wipClosing}</label>
        <strong>{formatVnd(wipClosing)}</strong>
      </div>
      <div className={erp.summaryItem}>
        <label className={erp.label}>{L.list.wipOrderCount}</label>
        <strong>{wipRows.length}</strong>
      </div>
    </div>
  );

  const listBody =
    !showTableLoading && items.length === 0 ? (
      <>
        {wipSummary}
        <div className={`${erp.empty} ${erp.emptyFill}`} data-testid={`${TEST_ID}-empty`}>{L.list.empty}</div>
      </>
    ) : !showTableLoading ? (
      <>
        {wipSummary}
        <div className={erp.tableWrapper}>
          <table className={erp.table}>
            <thead>
              <tr>
                <th>{L.list.colCode}</th>
                <th>{L.list.colProduct}</th>
                <th className={erp.colRight}>{L.detail.actualQty}</th>
                <th className={erp.colRight}>{L.list.colTotal}</th>
                <th className={erp.colRight}>{L.list.colUnitCost}</th>
                <th>{L.list.colProcessingLevel}</th>
              </tr>
            </thead>
            <tbody>
              {items.map(r => (
                <tr key={r.id} data-testid={`${TEST_ID}-row-${r.id}`}>
                  <td>
                    <button
                      type="button"
                      className={erp.codeLink}
                      onClick={() => navigate(`/gt/gia-thanh/${r.id}`)}
                    >
                      <code>{r.code}</code>
                    </button>
                  </td>
                  <td>{r.productName ?? r.productCode}</td>
                  <td className={erp.colRight}>{r.actualQty}</td>
                  <td className={erp.colRight}>{formatVnd(r.totalCost)}</td>
                  <td className={erp.colRight}>{formatVnd(r.unitCost)}</td>
                  <td>
                    <DocumentProcessingLevelPill
                      label={formatCostSheetProcessingLevel(r.processingLevel)}
                      compact
                      testId={`${TEST_ID}-level-${r.id}`}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </>
    ) : null;

  return (
    <div
      className={erp.voucherListRoot}
      data-voucher-list-page
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{
          title: L.list.title,
          titleIconClass: 'fas fa-industry',
          pageId: PAGE_ID,
        }}
        reportToolbar={reportToolbar}
        listTitle={L.list.listTitle}
        filters={listFilters}
        listLayoutVariant="erp-filter-bar"
        listHeaderClassName={LIN_ERP_LIST_FILTER_LAYOUT.header}
        listFiltersClassName={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        showTableLoading={showTableLoading}
        skeletonRows={Math.min(pageSize, 8)}
        footer={
          totalCount > 0 ? (
            <VoucherListPagination
              testIdPrefix={TEST_ID}
              page={page}
              totalCount={totalCount}
              pageSize={pageSize}
              onPageChange={setPage}
              onPageSizeChange={size => {
                setPageSize(size as ListPageSize);
                setPage(1);
              }}
            />
          ) : undefined
        }
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default GiaThanhListPage;
